{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C25"],
      "claim": "Olcegepant, a peptide-like CGRP antagonist with high transferability, had absolute oral bioavailability <1% in humans, demonstrating that large peptide-like structures with multiple H-bond donors can undergo near-complete first-pass elimination.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "UK-427,857 had an absolute bioavailability of 2.9 ± 1.7% in humans, providing direct low-F evidence from a structurally complex oral drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Almorexant had absolute oral bioavailability of approximately 11% in healthy subjects across multiple studies, well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Docetaxel had absolute oral bioavailability of 8% ± 6% in patients, attributed to CYP3A-mediated first-pass metabolism and P-gp efflux, supporting low F for a large lipophilic macrocyclic-like molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Dalfopristin, a large cyclic depsipeptide, had absolute bioavailability <5%, showing that macrocyclic peptide scaffolds can have very low oral F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Retosiban, the highest-transfer analogue, had absolute oral bioavailability of 17-25% in healthy female subjects, a range that straddles the 20% threshold; although the upper end is above threshold, the reported extensive first-pass elimination and lower bound below 20% make it weak contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of high-transfer experimental evidence from structurally related peptide-like and macrocyclic drugs shows absolute oral bioavailability well below 20% (e.g., <1%, 2.9%, 8%, 10-13%, <5%), supporting a low F prediction. One borderline analogue (retosiban, 17-25%) does not provide affirmative high-F evidence.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query molecule itself.",
    "The highest-transfer analogue (retosiban) has a borderline F of 17-25%, straddling the 20% threshold.",
    "Potential effects of formulation, food, or prodrug strategies on the query's oral exposure are not captured by the evidence.",
    "The query's specific transporter/metabolism profile (e.g., P-gp, CYP3A) is inferred from analogues rather than directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

